    {
      "label": "A",
      "phrases": [
        {
          "id": "V1-01",
          "zh": "梦醒时分睁开双眼"
        },
        {
          "id": "V1-02",
          "zh": "摊开书页上独自一人伫立"
        },
        {
          "id": "V1-03",
          "zh": "环顾四周却看不见"
        },
        {
          "id": "V1-04",
          "zh": "没有目标也没有出口"
        },
        {
          "id": "V1-05",
          "zh": "然后我听见的是"
        },
        {
          "id": "V1-06",
          "zh": "呼唤着我名字的你的声音"
        },
        {
          "id": "V1-07",
          "zh": "摸索着说出的言语"
        },
        {
          "id": "V1-08",
          "zh": "迈步向前走"
        }
      ]
    },
    {
      "label": "B",
      "phrases": [
        {
          "id": "V1-01",
          "zh": "从睡梦里睁开眼"
        },
        {
          "id": "V1-02",
          "zh": "摊开的书页上 只剩我一人"
        },
        {
          "id": "V1-03",
          "zh": "环顾四周 不见"
        },
        {
          "id": "V1-04",
          "zh": "方向 也没有出口"
        },
        {
          "id": "V1-05",
          "zh": "然后我听见了"
        },
        {
          "id": "V1-06",
          "zh": "那呼唤我名字的 你的声音"
        },
        {
          "id": "V1-07",
          "zh": "凭着摸索的话语"
        },
        {
          "id": "V1-08",
          "zh": "迈出了脚步"
        }
      ]
    }
  ]
}

